import Pagination from '../../Pagination/Pagination.js';
import StudiengangInformation from './StudiengangInformation/StudiengangInformation.js';
import BsConfirm from '../../Bootstrap/Confirm.js';

import ApiCms from '../../../api/factory/cms.js';
import ApiPermission from '../../../api/factory/permission.js';

export default {
	name: 'NewsComponent',
	components: {
		Pagination,
		StudiengangInformation,
	},
	inject: ['isMobile', 'isStudent'],
	data() {
		return {
			content: null,
			maxPageCount: 0,
			page_size: 100,
			page: 1,
			hasBasisNewsTypRPermission: false,
		};
	},
	watch: {
		'$p.user_language.value': function (sprache) {
			this.fetchNews();
		},
	},
	computed: {
		sprache: function () {
			return this.$p.user_language.value;
		},
	},
	methods: {
		async fetchNews() {
			let newsResponse = await this.$api.call(
				ApiCms.getNews(this.page, this.page_size, this.sprache),
			);
			this.content = newsResponse.data;
			this.maxPageCount = newsResponse.meta.row_count;

			document.querySelectorAll('#cms [data-confirm]').forEach((el) => {
				el.addEventListener('click', (evt) => {
					evt.preventDefault();
					BsConfirm.popup(el.dataset.confirm)
						.then(() => {
							Axios.get(el.href)
								.then((res) => {
									// TODO(chris): check for success then show message and/or reload
									location = location;
								})
								.catch((err) => console.error('ERROR:', err));
						})
						.catch(() => {});
				});
			});
			document.querySelectorAll('#cms [data-href]').forEach((el) => {
				el.href = el.dataset.href.replace(
					/^ROOT\//,
					FHC_JS_DATA_STORAGE_OBJECT.app_root,
				);
			});

			await this.$nextTick();
			this.formatExternalHtml();
		},
		async loadNewPageContent(data) {
			let newsResponse = await this.$api.call(
				ApiCms.getNews(data.page, data.rows),
			);
			this.content = newsResponse.data;

			await this.$nextTick();

			this.formatExternalHtml();
		},
		formatExternalHtml() {
			document
				.querySelectorAll('.news-list-item .card-header')
				.forEach((el) => {
					el.classList.add('fhc-primary');
				});
			document.querySelectorAll('.news-list-item .row').forEach((el) => {
				el.classList.add('w-100');
				el.classList.add('align-items-center');
			});
			document.querySelectorAll('.news-list-item .row h2').forEach((el) => {
				el.classList.add('mb-0');
			});
		},
		afterPageUpdated(event) {
			this.page = event.page;
			this.page_size = event.rows;
			this.$refs.newsPageHeading.scrollIntoView({ block: 'end' });
			this.loadNewPageContent(event);
		},
		async getPermissions() {
			const permissionsResponse = await this.$api.call(
				ApiPermission.getPermissions(
					[
						"basis/news:r",
					]
				)
			);

			if (permissionsResponse.meta.status === "success") {
				this.hasBasisNewsTypRPermission = permissionsResponse.data["basis/news:r"];
			}
		},
	},
	async created() {
		this.fetchNews();
		await this.getPermissions();
	},
	template: /*html*/ `
	<div :class="{'pb-3': isMobile}" class="overflow-x-hidden">
  		<div class="d-flex justify-content-between align-items-center">
			<h2 ref="newsPageHeading" class="fhc-primary-color">News</h2>
			<router-link
				v-if="hasBasisNewsTypRPermission"
				class="btn btn-primary mb-3"
				:to="{ name: 'NewsAdministration' }"
			>
				{{ $p.t('ui', 'newsAdministration') }} <i class="fas fa-cog m-0"></i>
			</router-link>
		</div>
		<hr/>
		<div class="container-fluid mt-4">
			<div class="row">
				<div v-if="maxPageCount" :class="isStudent ? 'col-12 col-md-8 col-xl-9' : 'col-12'" v-html="content"></div>
				<div
					v-else
					class="d-flex flex-row justify-content-center pt-3 pb-4"
					:class="isStudent ? 'col-12 col-md-8 col-xl-9' : 'col-12'"
				>
					<span>
						{{ $p.t('news/no_news') }}
					</span>
				</div>
				<div v-if="isStudent" class="col-12 col-md-4 col-xl-3">
					<studiengang-information></studiengang-information>
				</div>
			</div>
		</div>
		<pagination
			v-if="content?true:false"
			:page="page"
			:page_size="page_size"
			@pageUpdated="afterPageUpdated($event)"
			:maxPageCount="maxPageCount"
		></pagination>
	</div>
    `,
};
